    }
  ],
  "pancreatic": [
    {
      "title": "Coeliac trunk",
      "href": "/app/anatomy/colonvessels-pat012/arterial/index.html?segment=3:4"
    },
    {
      "title": "Common hepatic artery",
      "href": "/app/anatomy/colonvessels-pat012/arterial/index.html?segment=1:4"
